CH_C = [
dict(no=13, sec="mis", ic="⛵", t="第一次宣教旅行（上）", ref="徒13:1-52", kw="差派", kv="徒13:48",
 core="圣灵藉安提阿教会差派巴拿巴与扫罗；在塞浦路斯击败行法术者，在彼西底的安提阿会堂讲道；犹太人弃绝，福音转向外邦人，凡预定得永生的人都信了。",
 date="约主后 46–47 年", place="安提阿 → 塞浦路斯（撒拉米、帕弗）→ 别加 → 彼西底的安提阿", who="巴拿巴、扫罗（保罗）、马可、方伯士求保罗、行法术的以吕马", map=["antioch","salamis","paphos","perga","pantioch"], route=["antioch","seleucia","salamis","paphos","perga","pantioch"],
 story="安提阿教会有几位先知和教师。他们**事奉主、禁食的时候，圣灵说：要为我分派巴拿巴和扫罗**（{{徒13:2}}）；众人禁食祷告、按手，打发他们去。二人带着马可到塞浦路斯，从撒拉米走遍全岛到帕弗，方伯[[士求保罗]]想听神的道，行法术的以吕马抵挡，被扫罗（从此称**保罗**）宣告瞎眼，方伯就信了。马可在别加离开回耶路撒冷。在彼西底的安提阿会堂，保罗讲了一篇完整的讲章：从出埃及、士师、扫罗、大卫，讲到大卫的后裔耶稣，祂的死与复活应验 {{诗2:7}}、{{赛55:3}}、{{诗16:10}}；**靠着这人，凡信的人就在一切不能靠摩西律法称义的事上，都得称义了**（{{徒13:39}}）。下一个安息日几乎合城都来听，犹太人满心嫉妒；保罗、巴拿巴放胆说：我们就转向外邦人去（引 {{赛49:6}}）。外邦人欢喜，**凡预定得永生的人都信了**（{{徒13:48}}）。二人被赶逐，跺下脚上的尘土往以哥念去，门徒却满心喜乐，又被圣灵充满。",
 ol=[("13:1-3","圣灵差派：禁食祷告按手"),("13:4-12","塞浦路斯：方伯信主"),("13:13-41","彼西底安提阿：保罗的第一篇讲章"),("13:42-52","转向外邦人 · 预定得永生的都信了")],
 bg="塞浦路斯是巴拿巴的家乡（{{徒4:36}}），当时是罗马元老院行省，由“方伯”（proconsul）治理——路加的官衔用词精确，考古发现有“保卢斯”任该职的铭文。[[彼西底的安提阿]]是罗马殖民地，位于海拔约 1100 米的高原，属南加拉太。会堂礼拜的程序：读律法书、先知书，再请人“劝勉”（{{徒13:15}}）。",
 why=["安提阿教会成熟，有先知教师","圣灵在敬拜禁食中呼召","教会按手差派","先犹太人，后外邦人"], res="第一批南加拉太教会诞生；犹太人的弃绝反而打开外邦之门",
 bt="保罗的讲章是**救赎历史式讲道**的样板：从以色列史一直讲到基督，显明基督是大卫之约的应验（{{撒下7:12-16}}）。“我已经立你作外邦人的光”（{{赛49:6}}）本是指耶和华的仆人（弥赛亚），保罗却说主这样“吩咐我们”（{{徒13:47}}）：**基督的使命藉祂的使者延续**。",
 ct="「神向祖宗所应许的」（{{徒13:32}}）在耶稣复活中实现。称义的宣告直接对照**摩西之约的局限**：律法不能使人称义，唯有在基督里因信称义（{{徒13:38-39}}）——这是加拉太书与罗马书的核心，在保罗第一篇讲章中已经清楚。",
 rf="{{徒13:48}} 是改革宗**无条件拣选**的关键经文：不是「信了的人被预定」，而是“**凡预定得永生的人都信了**”——拣选是信心的源头（多特信经第一项教义第 9 条）。同时 13:46 说犹太人“断定自己不配得永生”：**神的主权与人的责任并存**。13:1-3 也是改革宗宣教的模式：**由地方教会经祷告差派**，而非个人自行出发（多特信经 1.3：神“差派传这大喜信息的使者”）。",
 hard=[("“预定”会不会使传福音变得没有必要？","恰恰相反：神既预定了目的（得永生），也预定了方法（传道与听道）。多特信经 1.3 说神“差派传这大喜信息的使者”；保罗正因神“在这城里我有许多的百姓”（{{徒18:10}}）而放胆继续讲。拣选是宣教最大的盼望。")],
 conf=[("dort",1,9),("dort",1,3)],
 app=["宣教从**敬拜、禁食、祷告**的地方教会开始。","被弃绝时“跺下脚上的尘土”，但心里仍“满心喜乐”——结果属于神。"],
 mn="⛵ 13：圣灵说分派——塞岛方伯信，彼西底讲章，预定的都信了（13:48）。"),
dict(no=14, sec="mis", ic="🗿", t="路司得：被当作神，又被石头打", ref="徒14:1-28", kw="路司得", kv="徒14:22",
 core="以哥念分裂；路司得人把巴拿巴、保罗当作宙斯和希耳米，转眼又用石头打保罗；回程坚固门徒、选立长老；回安提阿报告神为外邦人开了信道的门。",
 date="约主后 47–48 年", place="以哥念、路司得、特庇 → 回程 → 叙利亚的安提阿", who="保罗、巴拿巴、生来瘸腿的人、路司得的祭司", map=["iconium","lystra","derbe","antioch"], route=["pantioch","iconium","lystra","derbe","lystra","iconium","pantioch","perga","attalia","sea4","antioch"],
 story="在以哥念，信的人很多，城里的人却分成两党，二人避到路司得、特庇。在路司得，保罗医好一个**生来瘸腿**的人（与 3 章彼得的神迹平行）。众人用吕高尼话喊着说：神藉着人形降临在我们中间了！称巴拿巴为**丢斯（宙斯）**，保罗为**希耳米**，丢斯庙的祭司牵牛拿花圈要献祭。二人撕开衣裳：我们也是人！劝你们离弃这些虚妄，归向那创造天地海和其中万物的永生神；祂从来未尝不为自己留下证据，赏赐你们雨水和丰年（{{徒14:15-17}}）。随后犹太人从安提阿和以哥念来挑唆，众人用石头打保罗，以为他死了，拖到城外。门徒围着他，他就起来进城。二人回程经过各城，**坚固门徒的心……又说：我们进入神的国，必须经历许多艰难**（{{徒14:22}}），**在各教会中选立了长老**（{{徒14:23}}）。回到安提阿，述说神藉他们所行的一切事，并神怎样**为外邦人开了信道的门**（{{徒14:27}}）。",
 ol=[("14:1-7","以哥念：分成两党"),("14:8-18","路司得：被当作宙斯与希耳米"),("14:19-20","被石头打 · 起来进城"),("14:21-23","回程：坚固门徒 · 选立长老"),("14:24-28","回安提阿报告：信道的门")],
 bg="罗马诗人奥维德《变形记》记载：宙斯和希耳米曾化成人形来到弗吕家地区，只有一对老夫妇接待他们，其余人家都遭毁灭——难怪路司得人这次要“抢先”献祭。[[吕高尼话]]是当地方言，保罗起初听不懂，直到他们牵牛来才明白。路司得是罗马殖民地，也是提摩太的家乡（{{徒16:1}}）。",
 why=["福音进入外邦乡镇","神迹被异教世界观误读","群众情绪被犹太反对者操控","教会需要坚固与治理"], res="南加拉太教会建立长老治会；外邦宣教的成功引出割礼之争（15 章）",
 bt="保罗向没有圣经背景的异教徒传道，从**创造与普遍恩典**入手（{{徒14:15-17}}；参 17 章雅典讲道），这是**普遍启示**的教导：神藉雨水丰年为自己留下证据（{{罗1:20}}）。“进入神的国必须经历许多艰难”——国度已经来到，但在今世以十字架的样式展现。",
 ct="“选立长老”沿用以色列会众的**长老治理传统**（{{出18}}；{{民11:16}}），在新约教会中延续：神的约民一向由长老牧养。",
 rf="{{徒14:23}} 是改革宗**长老治会**的经文根据：使徒并没有在每城只设一位“主教”，而是在**各教会选立（复数）长老**；“选立”（cheirotoneō）原意是举手选举。比利时信条第 31 条：牧师、长老与执事都当“藉着祷告，经教会合法有序的选举而产生”。比利时信条第 2 条：我们藉着神对宇宙的创造、维护和管理，以及藉着圣言认识神——14:17 是前者，14:15 的宣讲是后者。",
 conf=[("bc",31),("bc",2)],
 app=["苦难不是失败的证据，而是进入神国的路（{{徒14:22}}）。","新信徒最需要的是**坚固、劝勉与有序的牧养**（长老）。"],
 mn="🗿 路司得：宙斯希耳米 → 石头打；回程三件事：坚固、劝勉、立长老。"),
dict(no=15, sec="mis", ic="⚖️", t="耶路撒冷会议", ref="徒15:1-35", kw="会议", kv="徒15:11",
 core="外邦人是否须受割礼才能得救？使徒和长老聚集议决：我们得救乃是因主耶稣的恩；外邦信徒不必受割礼，只须禁戒几件事，以保全教会合一。",
 date="约主后 49 年", place="叙利亚的安提阿 → 耶路撒冷 → 安提阿", who="保罗、巴拿巴、彼得、雅各（主的兄弟）、使徒和长老、犹大和西拉", map=["jerusalem","antioch"], route=["antioch","sidon","samaria","jerusalem"],
 story="有几个人从犹太下来教导弟兄：**你们若不按摩西的规条受割礼，不能得救**（{{徒15:1}}）。保罗、巴拿巴与他们大大争辩，教会就差他们上耶路撒冷见**使徒和长老**。会中先有许多辩论；彼得起来说：神藉着圣灵洁净外邦人的心，不分他们我们；为什么要把我们祖宗和我们所不能负的轭放在门徒的颈项上？**我们得救乃是因主耶稣的恩，和他们一样**（{{徒15:10-11}}）。巴拿巴、保罗述说神在外邦人中所行的神迹奇事。最后雅各引 {{摩9:11-12}}：神要重建大卫倒塌的帐幕，使余剩的人和外邦人都寻求主。他判断：不可难为归服神的外邦人，只要写信吩咐他们禁戒偶像的污秽和奸淫，并勒死的牲畜和血（{{徒15:19-20}}）。**使徒和长老并全教会**定意差犹大、西拉带信去：“圣灵和我们定意……”（{{徒15:28}}）。安提阿的门徒读了信，因信上安慰的话欢喜了。",
 ol=[("15:1-5","问题：割礼是得救的条件吗？"),("15:6-11","彼得：同样因主耶稣的恩得救"),("15:12-21","雅各引阿摩司：大卫的帐幕重建"),("15:22-35","会议的信：圣灵和我们定意")],
 bg="主后 49 年，罗马皇帝革老丢驱逐罗马的犹太人（{{徒18:2}}；史家苏埃托尼乌斯记载）；同一时期犹太地的奋锐党民族情绪高涨，对与外邦人交往的犹太信徒压力日增。保罗在 {{加2:1-10}} 可能记录了这次（或稍早一次）上耶路撒冷的情形。四项禁戒对应 {{利17–18}} 对「寄居在以色列中的外人」的要求。",
 why=["外邦人大量归信（13–14 章）","法利赛派信徒要求割礼与守律法","福音的核心受到威胁：恩典 + 行为？","教会以会议寻求圣经与圣灵的判断"], res="外邦人因恩典得救、不必受割礼；福音的大门正式定案，教会保持合一",
 bt="雅各引用阿摩司：**大卫倒塌的帐幕**（大卫王朝）在复活的基督里重建，而重建的目的是使**列国归于神的名下**（{{摩9:11-12}}）。外邦人不是作为“改宗的犹太人”进入，而是作为外邦人进入以色列的盼望——先知早已预告。",
 ct="割礼是亚伯拉罕之约的记号（{{创17}}），但亚伯拉罕是**在受割礼之前因信称义**（{{罗4:10-11}}）。基督来了，记号由洗礼取代（{{西2:11-12}}；比利时信条第 34 条），约的实质不变：恩典藉信心。禁戒的四项则是**为了犹太与外邦信徒同桌相交**的爱心规范，不是得救条件。",
 rf="改革宗从本章看见三件事：①**唯独恩典、唯独信心**（{{徒15:11}}；海德堡要理问答第 60 问）；②**教会会议**的合法性与权柄：使徒和长老（不是一位主教）聚集，按圣经议决，众教会遵行——这是改革宗**区会、大会**制度的根据（威斯敏斯特信条 31.3）；③会议的决定本身要以圣经为准（引阿摩司），会议可能出错，圣经不会（比利时信条第 7 条）。",
 hard=[("禁戒“血”的规定今天还有约束力吗？","改革宗通常认为四项禁戒是**当时情境下的爱心让步**，为保全犹太与外邦信徒的相交（参 {{林前8}}；{{罗14}}）；其中“奸淫”属道德律，永远有效；饮食方面的条款则随处境改变。保罗后来教导凡物都可吃，只要不绊倒人（{{林前10:25-33}}）。")],
 conf=[("hc",60),("w","wcf",31,3)],
 app=["教会的争议要回到**圣经与福音核心**，用有序的会议来处理，而不是分裂。","守住“唯独恩典”的同时，在次要事上为弟兄的良心让步。"],
 mn="⚖️ 49 年耶路撒冷会议：彼得讲恩典、雅各引阿摩司、一封信带来喜乐。"),
dict(no=16, sec="mis", ic="🌅", t="马其顿的呼声：腓立比", ref="徒15:36–16:40", kw="腓立比", kv="徒16:31",
 core="保罗与巴拿巴分开，带西拉、提摩太再出发；圣灵禁止往亚细亚，马其顿异象引福音入欧洲；吕底亚心被开导、狱卒全家信主受洗。",
 date="约主后 49–50 年（第二次旅行开始）", place="路司得 → 特罗亚 → 腓立比", who="保罗、西拉、提摩太、路加（“我们”）、吕底亚、被鬼附的使女、禁卒", map=["lystra","troas","philippi"], route=["antioch","tarsus","derbe","lystra","iconium","pantioch","troas","neapolis","philippi"],
 story="保罗与巴拿巴为马可起了争论，就彼此分开：巴拿巴带马可往塞浦路斯，保罗拣选西拉往叙利亚、基利家。在路司得，他带上**提摩太**，为了犹太人的缘故给他行割礼，并把耶路撒冷会议的条规交给各城（{{徒16:4}}）。**于是众教会信心越发坚固，人数天天加增**（{{徒16:5}}）。圣灵禁止他们在亚细亚讲道，耶稣的灵也不许他们往庇推尼；在特罗亚，保罗夜间见异象：有一个马其顿人说，请你过到马其顿来帮助我们（{{徒16:9}}）。从这里起叙述变成“**我们**”——路加加入了。在罗马殖民地腓立比的河边，卖紫色布的**吕底亚**听道，**主就开导她的心**，她和她一家都受了洗（{{徒16:14-15}}）。保罗赶出使女身上“巫鬼”，她的主人失了财路，把保罗、西拉拖到官长面前，打了许多棍下在监里。半夜他们**祷告唱诗**，地大震动，监门全开。禁卒要自杀，保罗喊：不要伤害自己！禁卒问：我当怎样行才可以得救？**当信主耶稣，你和你一家都必得救**（{{徒16:31}}）；他和属乎他的人立时都受了洗，全家因信神都很喜乐。次日保罗声明自己是**罗马人**，官长只得来赔不是。",
 ol=[("15:36-41","保罗与巴拿巴分开"),("16:1-5","提摩太加入 · 进展报告 ④"),("16:6-10","圣灵禁止 · 马其顿异象"),("16:11-15","吕底亚：主开导她的心"),("16:16-40","使女、监狱、地震、禁卒全家信主")],
 bg="[[腓立比]]是罗马殖民地，居民多为退伍军人后代，享有罗马公民权，以“像罗马”自豪；城中犹太人少到连会堂都没有（需十位犹太成年男子），所以只有河边的祷告处。[[罗马公民]]受法律保护，未经审判不得鞭打，官长违法要受重责——保罗善用公民身份保护新生的教会。吕底亚来自推雅推喇，那里以紫色染料行会闻名。",
 why=["保罗想回访已建立的教会","圣灵两次关门","异象打开马其顿的门","福音第一次进入欧洲"], res="欧洲第一个教会（腓立比）诞生，日后成为保罗最亲密的同工教会（参腓立比书）",
 bt="福音跨越到欧洲，是 1:8“直到地极”的重要一步。吕底亚（亚细亚的富商女子）、被鬼附的使女（奴隶）、禁卒（罗马下层公务员）——**三个截然不同的人，组成一个教会**（参 {{加3:28}}）。",
 ct="“你和你一家”——**以家为单位的圣约观**贯穿全本圣经：挪亚全家进方舟（{{创7:1}}）、亚伯拉罕全家受割礼（{{创17:23}}）、逾越节按家宰羊（{{出12:3}}）。使徒行传中有多次“全家受洗”（哥尼流 10 章、吕底亚 16:15、禁卒 16:33、基利司布 18:8；参 {{林前1:16}}），这是改革宗**婴孩洗礼**的重要旁证。",
 rf="“**主就开导她的心**”（{{徒16:14}}）——改革宗**有效呼召**的经典经文：人心归信是神的工作（多特信经 3/4.11-12），但神藉着保罗的讲道作成（“留心听保罗所讲的话”）。改革宗的婴孩洗礼不是建立在“全家”这一个词上，而是建立在**恩典之约的一致性**上（比利时信条第 34 条；海德堡要理问答第 74 问）；全家受洗的记载与这个圣约原则完全一致。",
 hard=[("禁卒“全家”受洗，能证明婴孩受洗吗？","经文没有说明家中是否有婴孩，单凭此不能“证明”。改革宗的论证是：①神的约一向包括信徒的儿女（{{创17:7}}；{{徒2:39}}）；②割礼的记号由洗礼取代（{{西2:11-12}}）；③新约没有任何把儿女排除在约外的命令；④“全家受洗”的模式正好符合这一圣约观。"),
       ("为什么给提摩太行割礼，却在加拉太书反对割礼？","当割礼被当作**得救的条件**时，保罗坚决反对（{{加5:2}}）；当它只是为了向犹太人传福音、避免不必要的绊脚石时，保罗为福音的缘故“向犹太人，我就作犹太人”（{{林前9:20}}）。提多是外邦人，保罗拒绝为他行割礼（{{加2:3}}）。")],
 conf=[("bc",34,"我们相信，根据神赐给我们儿女的应许，信徒的婴孩应当受洗，领受圣约的印记，正如过去以色列的婴孩基于同样的应许受割礼一样。"),("dort",3,12,"选民归信完全是神在我们里面做工，其间根本没有我们的参与，这是圣经特别强调的。")],
 app=["“关门”也是引导：被圣灵禁止的地方，常是另一扇门的预备。","在黑暗的监狱里也可以祷告唱诗；你的见证可能救一家人。"],
 mn="🌅 腓立比三人组：紫布吕底亚（心被开导）、巫鬼使女、禁卒全家——16:31 信主耶稣，你和你一家。"),
dict(no=17, sec="mis", ic="🏛️", t="帖撒罗尼迦、庇哩亚、雅典", ref="徒17:1-34", kw="雅典", kv="徒17:30-31",
 core="在帖撒罗尼迦“搅乱天下”，在庇哩亚天天考查圣经，在雅典亚略巴古向哲学家宣讲创造主、悔改与复活的审判。",
 date="约主后 50 年", place="帖撒罗尼迦 → 庇哩亚 → 雅典", who="保罗、西拉、提摩太、耶孙、庇哩亚人、伊壁鸠鲁与斯多亚学士、丢尼修、大马哩", map=["thessalonica","berea","athens"], route=["philippi","amphipolis","thessalonica","berea","athens"],
 story="保罗在帖撒罗尼迦会堂一连三个安息日**本着圣经与人辩论**，讲明基督必须受害、从死里复活（{{徒17:2-3}}）。有些人信了，犹太人却招聚匪类闹城，控告他们**搅乱天下**、违背凯撒说另有一个王耶稣（{{徒17:6-7}}）。庇哩亚人比帖撒罗尼迦人贤良，甘心领受这道，**天天考查圣经**，要晓得这道是与不是（{{徒17:11}}）。在雅典，保罗看见满城都是偶像，心里着急；伊壁鸠鲁和斯多亚的学士把他带到**亚略巴古**。保罗从“未识之神”的坛开始：创造宇宙的神不住人手所造的殿，也不需要人手服事；祂从一本造出万族，定准年限和疆界，要叫人寻求祂；“我们生活、动作、存留都在乎他”（引希腊诗人）。如今神吩咐各处的人都要悔改，因祂已定了日子要藉着所设立的人按公义审判天下，**并且叫他从死里复活**（{{徒17:30-31}}）。听见死人复活，有人讥诮，有人说再听，但丢尼修、大马哩等人信了。",
 ol=[("17:1-9","帖撒罗尼迦：搅乱天下的人"),("17:10-15","庇哩亚：天天考查圣经"),("17:16-21","雅典：满城偶像"),("17:22-34","亚略巴古讲道：创造、悔改、复活、审判")],
 bg="[[帖撒罗尼迦]]是马其顿省首府，位于厄纳齐亚大道上，自由城，官称“地方官”（politarchs）——路加用词经铭文证实。[[雅典]]已过黄金时代，但仍是哲学与文化的象征。[[伊壁鸠鲁派]]认为神明遥远不理人事，追求宁静的快乐；[[斯多亚派]]是泛神论倾向，讲顺应理性（logos）、自制。[[亚略巴古]]（战神山）既是地名，也是雅典处理宗教与教育事务的议会。保罗引用的“我们也是他所生的”出自斯多亚诗人亚拉图（Aratus）。",
 why=["在会堂以圣经证明基督","政治化的控告（另有一个王）","雅典的偶像与哲学","向无圣经背景的人从创造讲到审判"], res="帖撒罗尼迦、庇哩亚教会建立；雅典少数人信主；保罗往哥林多",
 bt="亚略巴古讲道是**从创造到审判的圣经世界观**的浓缩：创造（{{创1}}）、人类同出一本（{{创10}}）、神的护理与普遍启示、偶像的虚妄（{{赛44}}）、末日审判与复活。保罗没有从希腊哲学开始建造，而是**用圣经的故事改写他们的世界观**，只是借用他们的诗句作接触点。",
 ct="神“预先定准他们的年限和所住的疆界”（{{徒17:26}}）回响 {{申32:8}}：神按以色列的数目分定列国的疆界。列国的历史从来在神的约中有位置；现在“吩咐各处的人都要悔改”，**列国被召回到创造主面前**。",
 rf="改革宗护教学（范泰尔，威斯敏斯特神学院）以本章为“**前设护教**”的范例：保罗不接受中立地带，而是宣告雅典人“不认识”的神，揭示他们的偶像崇拜在神面前无可推诿（比利时信条第 2 条：受造物“足以使人知罪，且无可推诿”）。庇哩亚人是**唯独圣经**（Sola Scriptura）的典范：连使徒的话都要用圣经查验（比利时信条第 7 条）。",
 hard=[("保罗在雅典是否“失败”了，所以到哥林多才“在你们中间不知道别的，只知道耶稣基督并他钉十字架”？","这种读法缺乏根据：亚略巴古讲道明确宣告悔改、审判与基督复活，也有人信主（{{徒17:34}}）。{{林前2:2}} 针对的是哥林多人推崇修辞智慧的处境，不是否定雅典的讲道。")],
 conf=[("bc",7,"我们相信，圣经中包含了神全部的旨意；我们也相信它对人得救所必须信的一切真理作了充分的教导。"),("hc",52)],
 app=["像庇哩亚人一样：**听道之后，打开圣经查考**。","向世俗朋友传福音，可以从创造、意义、审判讲起，但一定要讲到**复活的基督**。"],
 mn="🏛️ 三城三态度：帖城闹（搅乱天下）、庇哩亚查（天天考查）、雅典讥（未识之神 → 复活审判）。"),
dict(no=18, sec="mis", ic="⛺", t="哥林多一年半", ref="徒18:1-22", kw="哥林多", kv="徒18:9-10",
 core="保罗在哥林多与百基拉、亚居拉织帐棚，主在异象中说“在这城里我有许多的百姓”；迦流拒审，保罗住了一年六个月，后经以弗所回安提阿。",
 date="约主后 50–52 年（迦流任方伯 51–52 年）", place="哥林多、坚革哩、以弗所 → 凯撒利亚 → 安提阿", who="保罗、亚居拉、百基拉、提多犹士都、基利司布、所提尼、方伯迦流", map=["corinth","ephesus","caesarea","antioch"], route=["athens","corinth","cenchreae","sea6","ephesus","sea2","sea1","caesarea","jerusalem","antioch"],
 story="保罗到哥林多，遇见因革老丢命令离开罗马的犹太人**亚居拉和百基拉**，同是**制造帐棚**为业，就与他们同住做工，每安息日在会堂辩论（{{徒18:1-4}}）。西拉、提摩太来到后，保罗专心传道。犹太人抗拒，保罗转到隔壁提多犹士都的家；管会堂的**基利司布和全家都信了主**，还有许多哥林多人听了就相信受洗。夜间主在异象中对保罗说：不要怕，只管讲……**因为在这城里我有许多的百姓**（{{徒18:9-10}}）。他就住了一年六个月。迦流作亚该亚方伯时，犹太人把保罗拉到公堂，迦流说这是你们自己的言语、名目和律法的事，不肯审问。保罗后来在坚革哩剪了头发（许愿），带百基拉、亚居拉到以弗所，留下他们，自己经凯撒利亚上耶路撒冷，再回安提阿（第二次旅行结束）。",
 ol=[("18:1-4","帐棚匠：亚居拉与百基拉"),("18:5-11","转向外邦 · 主说：我有许多百姓"),("18:12-17","迦流不受理：罗马法的保护"),("18:18-22","经以弗所回安提阿")],
 bg="[[哥林多]]是罗马亚该亚省首府，控制两港（东坚革哩、西利开翁），商业繁荣、道德败坏（“哥林多化”在希腊语中意为放荡）。**德尔斐铭文**（迦流铭文）记载迦流在 51–52 年任亚该亚方伯——这是整个保罗年表最重要的定点。迦流的“不受理”在法律上等于承认基督教属于犹太教内部问题、是合法宗教，为福音在帝国传播提供了约十年的法律保护。",
 why=["雅典之后来到大商城","与帐棚匠同工，自食其力","犹太人抗拒 → 转向外邦","主亲自鼓励：这城有我的百姓"], res="哥林多教会建立（参哥林多前后书）；保罗在此写帖撒罗尼迦前后书",
 bt="神对保罗说“有我与你同在”（{{徒18:10}}），正是神对摩西、约书亚、耶利米的应许（{{出3:12}}；{{书1:5}}；{{耶1:8}}）：**宣教士承接先知的位置与应许**。",
 ct="“我有许多的**百姓**”——用的是旧约指以色列的词（laos）。在败坏的哥林多，神已经有祂的约民，只是尚未被召出来。**拣选先于呼召，呼召藉着传道**。",
 rf="{{徒18:10}} 是改革宗宣教的信心根基：神的百姓是神预先认定的（多特信经 2.8：基督的死有效地“从各民、各族、各国、说各种语言的人中”拯救选民），所以传道者“只管讲，不要闭口”。保罗的“帐棚匠”模式也说明：**职业与事奉不对立**，但当条件许可时，传道人专心传道（{{徒18:5}}；参 {{林前9:14}}）。",
 conf=[("dort",2,8,"这意味着，神定意叫基督藉着十字架上所流的宝血坚立新约，有效地从各民、各族、各国、说各种语言的人中拯救那些（而且只有那些）从永恒中就蒙拣选得救的人，就是圣父赐给基督的那些人；")],
 app=["在最败坏的城市，也有神的百姓：不要怕，只管讲。","夫妇同工（百基拉与亚居拉）是教会极大的祝福：开放你的家与职业为福音所用。"],
 mn="⛺ 帐棚匠三人组 + 迦流铭文（51–52 年）= 保罗年表的锚点；“在这城里我有许多的百姓”。"),
dict(no=19, sec="mis", ic="🔥", t="以弗所：道大大兴旺", ref="徒18:23–19:41", kw="以弗所", kv="徒19:20",
 core="亚波罗得更准确的教导；约翰门徒受洗领受圣灵；保罗在推喇奴学房讲论两年，邪术书被焚；亚底米银匠暴动，主的道却大大兴旺而且得胜。",
 date="约主后 52–55 年（第三次旅行，以弗所约三年）", place="以弗所（亚细亚省）", who="亚波罗、百基拉、亚居拉、约翰的门徒、士基瓦的七个儿子、银匠底米丢、书记", map=["ephesus","corinth","antioch"], route=["antioch","tarsus","derbe","lystra","iconium","pantioch","ephesus"],
 story="亚历山大人**亚波罗**，有学问、最能讲解圣经，却只晓得约翰的洗礼；百基拉、亚居拉把神的道给他讲解更加详细（{{徒18:24-26}}）。保罗来到以弗所，遇见约十二个门徒只受过约翰的洗，连圣灵都没有听说过；保罗告诉他们约翰是要人信那在他以后来的耶稣，他们就奉主耶稣的名受洗，保罗按手，圣灵降在他们身上（{{徒19:1-7}}）。保罗在会堂三个月，后在**推喇奴的学房**天天辩论，两年之久，**叫一切住在亚细亚的，都听见主的道**（{{徒19:10}}）。士基瓦的七个儿子冒用耶稣的名赶鬼，反被恶鬼制伏；许多行邪术的把书拿来焚烧，书价五万块钱（{{徒19:19}}）。**主的道大大兴旺，而且得胜**（{{徒19:20}}）。银匠**底米丢**因生意受损，鼓动众人在剧场喊了两小时“大哉，以弗所人的亚底米啊”；城里的书记平息了骚乱。",
 ol=[("18:23-28","第三次旅行开始 · 亚波罗"),("19:1-7","约翰的门徒受洗领受圣灵"),("19:8-12","推喇奴学房两年：全亚细亚听道"),("19:13-20","士基瓦七子 · 焚书 · 进展报告 ⑤"),("19:21-41","亚底米暴动")],
 bg="[[以弗所]]是亚细亚省最大城市（约 25 万人），港口与陆路枢纽；**亚底米神庙**是古代世界七大奇观之一，比雅典帕特农神庙大四倍，也是银行与朝圣中心；银匠制作神庙小银龛贩卖。以弗所以[[以弗所文字]]（Ephesia grammata，护身咒语）闻名，邪术书籍盛行。古剧场可容约两万五千人，今天仍存。",
 why=["以弗所是亚细亚的福音战略中心","教导不完全的门徒需要被补足","福音冲击邪术与偶像经济","利益受损者发动暴动"], res="亚细亚众教会建立（歌罗西、老底嘉等，参启示录七教会）；保罗计划经马其顿往耶路撒冷再到罗马（19:21）",
 bt="焚烧邪术书，与旧约中归正的以色列除掉偶像相呼应（{{代下34:3-7}}）。“主的道大大兴旺，而且得胜”——**道本身是主语**：使徒行传的进展报告把神的道当作不断生长的活物（参 {{赛55:10-11}}）。福音胜过黑暗权势，是基督捆绑壮士的延续（{{路11:21-22}}）。",
 ct="约翰的洗礼属于**预备阶段**（悔改、指向将来者）；奉耶稣之名的洗礼标志着人进入**已经成就的新约**。这十二人的经历是救赎历史过渡期的特殊情况，表明旧约的最后先知（约翰）的门徒也被收入基督的教会。",
 rf="改革宗关于 19:1-7：这些人是**过渡期**的约翰门徒，还不是完整意义上的基督徒，因此不能作为「信主后第二次领受圣灵」的规范。第一诫（海德堡要理问答第 94 问）要求我们“躲避、逃离一切偶像崇拜、巫术、邪术、迷信”——以弗所人焚书正是真悔改的果子。保罗手巾围裙的医治是**特殊的使徒神迹**（{{徒19:11}}“非常的奇事”），不是今天的常规。",
 hard=[("保罗的手巾围裙能治病，今天可以效法吗？","路加特别说这是“非常的奇事”（{{徒19:11}}），即连在使徒时代也属罕见。这是神为印证使徒职分所行的（{{林后12:12}}）；士基瓦七子的失败也警告：耶稣的名不是可操控的魔法。改革宗正统认为这类印证使徒的神迹恩赐随使徒时代结束而止息，但神今天仍按祂的旨意垂听祷告、施行医治。")],
 conf=[("hc",94),("hc",95)],
 app=["福音会碰触钱包和生意：真悔改愿意付上代价（焚书五万）。","持续、系统的教导（两年天天讲论）是福音扎根一个地区的关键。"],
 mn="🔥 以弗所：亚波罗补课、十二门徒、学房两年、七子挨打、焚书五万、亚底米暴动——19:20 第五个进展报告。"),
]
